#include <bits/stdc++.h>
using namespace std;

const int N = 100000 + 5;
const int L = 18;              // 2^17 > 1e5

int n, q;
vector<int> children[N];
int up[L][N];                  // up[j][u]: 从 u 向上走 2^j 步
int down[L][N];                // down[j][u]: 从 u 沿最小儿子走 2^j 步

void dfs(int u) {
    for (int j = 1; j < L; ++j)          // 向上：父结点已就绪，自上而下
        up[j][u] = up[j - 1][up[j - 1][u]];
    for (int v : children[u]) dfs(v);
    for (int j = 1; j < L; ++j)          // 向下：子结点已就绪，自下而上
        down[j][u] = down[j - 1][down[j - 1][u]];
}

int jump(int go[L][N], int u, int step) {
    for (int j = 0; j < L; ++j)
        if ((step >> j) & 1) u = go[j][u];
    return u;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> q;
    up[0][1] = 1;                  // 根结点向上仍停在根
    down[0][1] = 1;
    for (int i = 2; i <= n; ++i) {
        int p; cin >> p;
        up[0][i] = p;
        children[p].push_back(i);
    }
    for (int u = 1; u <= n; ++u)
        down[0][u] = children[u].empty() ? u : *min_element(children[u].begin(), children[u].end());
    dfs(1);
    while (q--) {
        int s, k; cin >> s >> k;
        int cur = s;
        for (int i = 0; i < k; ++i) {
            long long a; cin >> a;
            cur = (a > 0) ? jump(up, cur, (int)a) : jump(down, cur, (int)(-a));
        }
        cout << cur << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100000 + 5;
const int MOD = 1000000000;   // 10^9，非质数，不能求逆元

int deg[N], fac[N], pre[N], suf[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n == 1) {             // 单结点树只有 1 种遍历序
        cout << 1 << '\n';
        return 0;
    }
    fac[0] = 1;
    for (int i = 1; i <= n; ++i) fac[i] = (long long)fac[i - 1] * i % MOD;
    for (int i = 1; i < n; ++i) {
        int u, v; cin >> u >> v;
        ++deg[u]; ++deg[v];
    }
    pre[0] = 1;
    for (int i = 1; i <= n; ++i) pre[i] = (long long)pre[i - 1] * fac[deg[i] - 1] % MOD;
    suf[n + 1] = 1;
    for (int i = n; i >= 1; --i) suf[i] = (long long)suf[i + 1] * fac[deg[i] - 1] % MOD;
    long long ans = 0;
    for (int i = 1; i <= n; ++i)
        ans = (ans + (long long)pre[i - 1] * fac[deg[i]] % MOD * suf[i + 1]) % MOD;
    cout << ans << '\n';
    return 0;
}
